export const setupFile = "SUPABASE_SETUP.sql";
const adminEmail = "admin@workledger.invalid";
const header = `-- WorkLedger Compliance: complete database setup for a NEW Supabase project.
-- Generated by scripts/build-setup-sql.mjs from supabase/migrations/. Do not edit by hand.
--
-- Before running:
--   1. Use a new Supabase project. Never run this on the original WorkLedger project.
--   2. Authentication > Users > Add user: ${adminEmail}, a strong password, Auto Confirm User on.
-- Then run this whole file once in the SQL editor. It is a single transaction: if anything fails,
-- nothing is changed and you can run it again after fixing the cause.`;
const preflight = `-- Stop early, changing nothing, on the wrong project or without the administrator's Auth user.
do $$
begin
  if to_regclass('public.profiles') is not null or to_regclass('public.tasks') is not null then
    raise exception 'WorkLedger tables already exist in this project. Run this file only on a new, empty Supabase project.';
  end if;
  if not exists (select 1 from auth.users where lower(email) = '${adminEmail}') then
    raise exception 'Create the Auth user ${adminEmail} first (Authentication > Users > Add user, Auto Confirm User on), then run this file again.';
  end if;
end $$;`;
const firstAdmin = `-- ===== First administrator =====
-- Links the Auth user checked above to the administrator profile.
insert into public.profiles (auth_user_id, username, full_name, display_name, role)
select id, 'admin', 'Administrator', 'Admin', 'admin' from auth.users where lower(email) = '${adminEmail}';`;
// Each migration wraps itself in begin/commit; drop those so the combined file is one transaction.
function unwrap(name: string, sql: string) {
  const isControl = (line: string) => ["begin;", "commit;"].includes(line.trim());
  const lines = sql.split("\n");
  if (lines.filter(isControl).map((l) => l.trim()).join(" ") !== "begin; commit;")
    throw new Error(`${name} must contain exactly one begin; and one commit;`);
  return lines.filter((line) => !isControl(line)).join("\n").trim();
}
// Every migration in order, then the first administrator, as one all-or-nothing script for the SQL editor.
export function setupSql(migrations: { name: string; sql: string }[]) {
  return [
    header,
    "begin;",
    preflight,
    ...migrations.map(({ name, sql }) => `-- ===== ${name} =====\n${unwrap(name, sql)}`),
    firstAdmin,
    "commit;",
  ].join("\n\n") + "\n";
}
